#pragma once

#include "assets/Catalog.h"

#include <nlohmann/json.hpp>

#include <filesystem>
#include <optional>
#include <set>
#include <string>
#include <vector>

namespace aige {

// Asset sourcing (development_plan.md 7.9, place-assets.md): for each thing a
// build needs, where its art comes from — the project, the AIGE library, the
// web, generated by the Art tool, or a placeholder — by the need's importance
// and the component's policy, with licences checked and credits written.

enum class Importance { Critical, Normal, Optional };
const char* ImportanceName(Importance importance);

struct NeedProfile {
    Importance importance = Importance::Normal;
    bool styleCritical = false; // must match the style closely (buildings, terrain, piece sets, what's seen often)
};

// critical: essential and large or structural (buildings, terrain, roads,
// walls, fences); normal: essential, small; optional: adaptable. Style-critical:
// a building, terrain or tile set, a piece set, or something seen 20 times or more.
NeedProfile ProfileOf(const std::string& layer, bool essential, bool joined, int uses);

// Which licences a project takes (place-assets.md §7): CC0, CC-BY and OGA-BY by
// default; CC-BY-SA only with share-alike allowed; never an unknown licence.
struct LicencePolicy {
    bool shareAlike = false;
    std::set<std::string> extra; // more the project allows, by their normalised names
    // The licence as one of: CC0, CC-BY, CC-BY-SA, OGA-BY, GPL, ..., or "" if unreadable.
    static std::string Normalise(const std::string& licence);
    bool Allowed(const std::string& licence) const;
    bool NeedsAttribution(const std::string& licence) const;
};

// The project's sourcing settings (places/sourcing.json).
struct SourcingSettings {
    bool webSearch = false; // search the web for free art (off unless the project turns it on)
    LicencePolicy licences;
    // How a build finds its art when a part says "auto" (the Build panel's default): "search"
    // (the project, the user's library, the web, then the Art tool: found art is the most
    // reliable), "generate", "library", "project" or "auto".
    std::string defaultSource = "search";
};
SourcingSettings ReadSourcingSettings(const std::filesystem::path& projectRoot);
void WriteSourcingSettings(const std::filesystem::path& projectRoot, const SourcingSettings& settings);

// What one need's candidates are, by where they come from (each list best first).
struct SourceCandidates {
    std::vector<Candidate> project; // in the project (imported, generated or fetched before)
    std::vector<Candidate> library; // in the AIGE library, not yet in the project
    std::vector<Candidate> web;     // fetched from the web for this build
};

// What has been tried for a need already (so the procedure moves on).
struct Tried {
    bool web = false;
    bool generate = false;
};

struct Decision {
    std::string step;   // A1..A7, G (place-assets.md §5)
    std::string action; // use, import, adapt, generate, web, drop, placeholder
    std::string source; // project, library, web, generated, none
    std::optional<Candidate> candidate; // a copy (it points into the catalog, which outlives it)
    std::string reason;
    bool warn = false;  // the user should know (web art for a style-critical need)
};

// The decision procedure for one need under `policy` (auto, project, library,
// web, generate). Candidates whose licence the policy doesn't allow are never used.
Decision Decide(const std::string& policy, const NeedProfile& profile, const SourceCandidates& candidates, const LicencePolicy& licences,
                bool webEnabled, bool canGenerate, const Tried& tried);

// Candidates with a licence the policy doesn't allow, left out (a project
// asset with no licence recorded is the project's own, and stays).
std::vector<Candidate> Licensed(const std::vector<Candidate>& candidates, const LicencePolicy& licences);

// The AIGE library: a curated, pre-analysed collection installed per project
// (<project>/library/catalog.json, entries in the catalog's own form). Until
// it exists, it has nothing.
Catalog LoadAssetLibrary(const std::filesystem::path& projectRoot);

// CREDITS.md: the assets a project uses that need attribution, in a section
// the engine keeps (between markers; the rest of the file is the user's).
// `used`: [{path, licence, author, url, source}].
bool WriteCredits(const std::filesystem::path& projectRoot, const nlohmann::json& used, const LicencePolicy& licences);

} // namespace aige
